// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();

        vm.deal(address(c), 1 ether);

        ProxyOwner p = new ProxyOwner();
        SimpleWallet c2 = address(new SimpleWallet()) == address(0) ? c : new SimpleWallet();
        SimpleWallet cOwned = p.deployC();

        vm.deal(address(cOwned), 1 ether);

        AttackerOwner ao = new AttackerOwner(address(rev));
        SimpleWallet cAtt = ao.c();
        vm.deal(address(cAtt), 1 ether);

        bool ok;
        try ao.callWithdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false);
    }
}

contract Reverter {
    fallback() external payable {
        revert("nope");
    }
    receive() external payable {
        revert("nope");
    }
}

contract AttackerOwner {
    SimpleWallet public c;
    address public reverter;
    constructor(address _reverter) {
        reverter = _reverter;
        c = new SimpleWallet();
    }
    receive() external payable {
        (bool success, ) = reverter.call{value: msg.value}("");
        if (!success) {
            revert("forward failed");
        }
    }
    function callWithdraw(uint256 _v) public {
        c.withdraw(_v);
    }
}

contract ProxyOwner {
    function deployC() public returns (SimpleWallet) {
        SimpleWallet cc = new SimpleWallet();
        return cc;
    }
}
